    i = 0
    while i < len(row):
        if row[i] == 0:
            i += 1
            continue
        j = i
        while j < len(row) and row[j] != 0:
            j += 1
        runs.append(row[i:j])
        i = j
    return runs


def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    templates = _runs(grid[0]) + (_runs(grid[-1]) if h > 1 else [])
    for r in range(1, h - 1):
        for c, color in enumerate(grid[r]):
            if color == 0:
                continue
            for seq in templates:
                if color in seq:
                    k = seq.index(color)
                    start = c - k
                    for j, value in enumerate(seq):
                        cc = start + j
                        if 0 <= cc < w:
                            out[r][cc] = value
                    break
    return out
